verifications.command:
uv run -- python -c "
import tomllib, pathlib, re
data = tomllib.loads(pathlib.Path('pyproject.toml').read_text())
def name(s): return re.split(r'[><=!;@\[]', s.strip())[0].strip().lower()
deps = set()
for s in data['project'].get('dependencies', []): deps.add(name(s))
for g in data['project'].get('optional-dependencies', {}).values():
    for s in g:
        if isinstance(s, str): deps.add(name(s))
for g in data.get('dependency-groups', {}).values():
    for s in g:
        if isinstance(s, str): deps.add(name(s))
deps.discard('')
inv = pathlib.Path('docs/development/dependency-inventory.md').read_text().lower()
missing = [p for p in sorted(deps) if not re.search(r'\\b' + re.escape(p) + r'\\b', inv)]
print('MISSING:', missing) if missing else print(f'OK: all {len(deps)} deps present in inventory')
"
